<?php
namespace qqworld_collector\module\collect_filter; class get_real_address extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $download_args['recursive'] = false; $link = explode("\r\n", $item); if (count($link)>1) { $download_args['method'] = 'post'; $download_args['content'] = $link[1]; $response = apply_filters( 'qqworld-collector-download-from-url', $link[0], $download_args); $location = wp_remote_retrieve_header($response, 'Location'); if (!$location) $location = wp_remote_retrieve_header($response, 'location'); if ($location) $item = $location; } else { $header = apply_filters( 'qqworld-collector-get-headers-from-url', $item, $download_args); $preg = preg_match_all('/Location: (.*)/i', $header, $match); if ($preg) { $item = trim(end($match[1])); } else { $response = wp_remote_get($item, $download_args); if (!is_wp_error($response)) { $response_object = $response['http_response']->get_response_object(); if (isset($response_object->url)) $item = $response_object->url; } else { do_action( 'qqworld-collector-log', $this->log_id, 'Filter - get_real_address Error:', $response->get_error_message() ); } } } return $item; } } ?>